        CREATE TABLE IF NOT EXISTS users (
            username TEXT PRIMARY KEY,
            email TEXT,
            password_verifier TEXT
        )
    ''')
    conn.commit()

def hash_password(password):
    return password.encode('utf-8').hex()

def process_command(conn, command_line):
    tokens = command_line.split()
    if not tokens:
        return

    cmd = tokens[0]
    try:
        if cmd == 'add':
            if len(tokens) != 4:
                raise ValueError("Invalid command: add")
            username, email, password = tokens[1], tokens[2], tokens[3]
            cursor = conn.cursor()
            cursor.execute('SELECT username FROM users WHERE username = ?', (username,))
            if cursor.fetchone():
                log_error(f"Username {username} already exists")
                return
            cursor.execute('INSERT INTO users (username, email, password_verifier) VALUES (?, ?, ?)',
                          (username, email, hash_password(password)))
            conn.commit()
            log_info(f"Added user {username}")

        elif cmd == 'find':
            if len(tokens) != 3:
                raise ValueError("Invalid command: find")
            column, value = tokens[1], tokens[2]
            cursor = conn.cursor()
            cursor.execute('SELECT username, email FROM users WHERE ? = ?', (column, value))
            results = cursor.fetchall()
            if not results:
                print("NO MATCHES")
                log_info(f"Found 0 users for {column}={value}")
            else:
                for row in results:
                    print(f"USER: {row[0]} {row[1]}")
                log_info(f"Found {len(results)} users for {column}={value}")

        else:
            raise ValueError("Invalid command")

    except ValueError as e:
        log_error(f"Invalid command: {command_line}")
    except sqlite3.Error as e:
        log_error(f"Database error: {str(e)}")

def log_info(message):
    logging.info(message)

def log_error(message):
    logging.error(message)

def main():
    setup_logging()
    conn = sqlite3.connect('users.db')
    create_table(conn)

    for line in sys.stdin:
        line = line.strip()
        if line:
            process_command(conn, line)

    conn.close()

if __name__ == "__main__":
    main()

