import sqlite3
import sys
import logging
from datetime import datetime, timezone
from typing import List, Optional

def setup_logging():
    logging.basicConfig(
        filename='userdb.log',
        level=logging.INFO,
        format='%(asctime)sZ %(levelname)s %(message)s',
        datefmt='%Y-%m-%dT%H:%M:%S'
    )

def hash_password(password: str) -> str:
    return password.encode('utf-8').hex()

def process_command(command: str, conn: sqlite3.Connection) -> None:
    tokens = command.split()
    if not tokens:
        return

    if tokens[0] == 'add' and len(tokens) == 4:
        username, email, password = tokens[1], tokens[2], tokens[3]
        cursor = conn.cursor()
        try:
            cursor.execute('''
                INSERT INTO users (username, email, password_verifier)
                VALUES (?, ?, ?)
            ''', (username, email, hash_password(password)))
            conn.commit()
            log_message('INFO', f'Added user {username}')
        except sqlite3.IntegrityError:
            log_message('ERROR', f'Username {username} already exists')
        except Exception as e:
            log_message('ERROR', f'Database error: {str(e)}')
    elif tokens[0] == 'find' and len(tokens) == 3:
        column, value = tokens[1], tokens[2]
        cursor = conn.cursor()
        try:
            cursor.execute('''
                SELECT username, email FROM users
                WHERE {column} = ?
            '''.format(column=column), (value,))
            results = cursor.fetchall()
            if results:
                for username, email in results:
                    print(f'USER: {username} {email}')
            else:
                print('NO MATCHES')
            log_message('INFO', f'Found {len(results)} users for {column}={value}')
        except Exception as e:
            log_message('ERROR', f'Database error: {str(e)}')
    else:
        log_message('ERROR', f'Invalid command: {command}')

def log_message(level: str, message: str) -> None:
    logging.log(getattr(logging, level.upper()), message)

def main():
    setup_logging()
    conn = sqlite3.connect('users.db')
    conn.execute('''
        CREATE TABLE IF NOT EXISTS users (
            username TEXT PRIMARY KEY,
            email TEXT,
            password_verifier TEXT
        )
    ''')
    conn.commit()

    for line in sys.stdin:
        line = line.strip()
        if line:
            process_command(line, conn)

    conn.close()

if __name__ == '__main__':
    main()
